.libPaths(c('work/stage5_Rlib',.libPaths()));library(susieR)
d<-read.csv('work/stage6_foxp2_susie_aligned.csv');p<-nrow(d);nref<-503L;b<-readBin('work/stage6_foxp2_reference_genotypes_float64.bin','double',n=p*nref,size=8,endian='little');stopifnot(length(b)==p*nref);g<-matrix(b,nrow=nref,ncol=p);rm(b);common<-readLines('work/stage6_foxp2_fin_common_ids.txt');keep<-d$rs %in% common;g<-g[,keep,drop=FALSE];d<-d[keep,];p<-nrow(d);stopifnot(p==3019);R<-cor(g);rm(g);dimnames(R)<-list(d$rs,d$rs);stopifnot(max(abs(diag(R)-1))<1e-6)
cat('Computing eigendecomposition for',p,'variants\n');flush.console();e<-eigen(R,symmetric=TRUE);attr(R,'eigen')<-e
names<-c('MVP_insomnia_effN','MVP_insomnia_totalN','FinnGen_HFRS');N<-c(253769,408138,500737);zs<-list(d$mvp_z_anchor,d$mvp_z_anchor,d$hfrs_z_anchor);diagout<-list();fitout<-list()
for(i in seq_along(names)){
 names(zs[[i]])<-d$rs;cat('Starting',names[i],'\n');flush.console();lambda<-estimate_s_rss(zs[[i]],R,n=N[i]);set.seed(42);f<-susie_rss(z=zs[[i]],R=R,n=N[i],L=10,estimate_residual_variance=FALSE,max_iter=500,coverage=.95,verbose=FALSE);cs<-f$sets$cs;sets<-data.frame(component=integer(),size=integer(),lead=character(),lead_pip=numeric(),min_abs_corr=numeric());if(length(cs)>0)for(k in seq_along(cs)){ids<-cs[[k]];lead<-ids[which.max(f$pip[ids])];sets<-rbind(sets,data.frame(component=f$sets$cs_index[k],size=length(ids),lead=d$rs[lead],lead_pip=f$pip[lead],min_abs_corr=f$sets$purity[k,'min.abs.corr']))}
 write.csv(sets,paste0('outputs/stage6_foxp2_eurcommon_',names[i],'_susie_candidate_sets.csv'),row.names=FALSE);saveRDS(f,paste0('work/stage6_foxp2_eurcommon_',names[i],'_susie.rds'));diagout[[i]]<-data.frame(trait=names[i],working_n=N[i],n_variants=p,estimated_lambda=lambda,reference_n=nref,rank_bound=nref-1,min_eigenvalue=min(e$values),converged=f$converged,iterations=f$niter,n_credible_sets=length(cs),maximum_pip=max(f$pip));cat('Finished',names[i],'lambda',lambda,'sets',length(cs),'converged',f$converged,'\n');flush.console()
}
